# Adds the OPERA DSWx-S1 (radar) water maps of Kerr County to docs/opera-s1.json for game/nasa-s1.js
# Run: python3 -I build_opera_s1.py <s1_0704.tif> <s1_0711.tif> <out_js> <provenance.json>
import sys, json, io, base64, hashlib, numpy as np, tifffile
from PIL import Image
E0,E1,N0,N1=465000,510000,3310020,3335040   # UTM 14N box: Hunt - Ingram - Kerrville - Center Point - Comfort
out=[];man=[]
for p,d in ((sys.argv[1],'2025-07-04'),(sys.argv[2],'2025-07-11')):
    t=tifffile.TiffFile(p);pg=t.pages[0];a=pg.asarray();tg={x.name:x.value for x in pg.tags.values()};x0,y0=tg['ModelTiepointTag'][3],tg['ModelTiepointTag'][4]
    c0,c1=int((E0-x0)/30),int((E1-x0)/30);r0,r1=int((y0-N1)/30),int((y0-N0)/30);s=a[r0:r1,c0:c1]
    h,w=(s.shape[0]//3)*3,(s.shape[1]//3)*3;q=s[:h,:w].reshape(h//3,3,w//3,3)
    water=(q==1).any(axis=(1,3));nod=(q==255).all(axis=(1,3))
    img=np.zeros((h//3,w//3,3),np.uint8);img[:]=(14,24,40);img[nod]=(60,60,60);img[water]=(90,190,255)
    buf=io.BytesIO();Image.fromarray(img).convert('P',palette=Image.ADAPTIVE,colors=4).save(buf,'PNG',optimize=True)
    out.append({'date':d,'png':'data:image/png;base64,'+base64.b64encode(buf.getvalue()).decode(),'w':w//3,'h':h//3,'boxKm':[(E1-E0)/1000,(N1-N0)/1000],
      'validPct':round(100*float((s!=255).mean()),1),'waterKm2':round(float((s==1).sum())*900/1e6,2),'maskedPx':int(((s>1)&(s<255)).sum()),'px':int(s.size)})
    man.append({'file':p.split('/')[-1],'sha256':hashlib.sha256(open(p,'rb').read()).hexdigest(),'product':'OPERA L3 DSWx-S1 V1, layer BWTR (binary water, Sentinel-1 radar)'})
    print(d,out[-1]['validPct'],out[-1]['waterKm2'],out[-1]['maskedPx'],len(out[-1]['png']))
D={'utm14N_box_m':[E0,N0,E1,N1],'display':'3x3 pixel blocks; a block is drawn as water if any 30 m pixel in it is water','files':out}
open(sys.argv[3],'w').write('/* AUTO-GENERATED by tools/build_opera_s1.py from NASA/JPL OPERA DSWx-S1 downloads. */\n(function(r){const D='+json.dumps(D,separators=(',',':'))+';if(typeof module!=="undefined"&&module.exports)module.exports=D;else r.NasaS1=D;})(typeof window!=="undefined"?window:globalThis);\n')
m=json.load(open(sys.argv[4]));m['sourceFiles']=[f for f in m['sourceFiles'] if 'DSWX-S1' not in f['file']]+man;m['processing'].append('OPERA DSWx-S1: cut to the UTM 14N box 465-510 km E, 3310-3335 km N (Kerr County); water area = water pixels x 900 m2; thumbnail shows a 90 m block as water if any 30 m pixel in it is water');json.dump(m,open(sys.argv[4],'w'),indent=1)
